mapper.select:
/* Notice01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* Notice01Mapper.countNodeInSelfSubtree */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{rootNodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT COUNT(1) FROM node_tree T WHERE T.NODE_CD = #{targetNodeCd}

/* Notice01Mapper.countNodeInSite */
SELECT
    COUNT(1)
FROM TB_SITE_NODE N
WHERE N.CMPNY_CD = #{cmpnyCd}
  AND N.SITE_CD = #{siteCd}
  AND N.NODE_CD = #{nodeCd}

/* Notice01Mapper.countDailyUser */
SELECT
    COUNT(1)
FROM TB_DAILY_USER D
WHERE D.CMPNY_CD = #{cmpnyCd}
  AND D.USER_CD = #{userCd}
  AND D.USE_YN = 'Y'

/* Notice01Mapper.selectNoticeList */ SELECT
, ( SELECT COUNT(1) FROM TB_NOTICE_FILE NF WHERE NF.CMPNY_CD = A.CMPNY_CD AND NF.NOTICE_ID = A.NOTICE_ID ) AS fileCnt , CASE WHEN K.LAST_READ_DATE IS NULL THEN 1 ELSE 0 END AS isUnread , CASE WHEN K.LAST_READ_DATE IS NOT NULL AND A.UPDATE_DATE IS NOT NULL AND A.UPDATE_DATE > K.LAST_READ_DATE THEN 1 ELSE 0 END AS isUpdated , ( SELECT CASE WHEN A.TARGET_SCOPE = 'ALL' THEN '전사' ELSE CONCAT( IFNULL(MIN(TGT.LABEL), '') , CASE WHEN COUNT(1) > 1 THEN CONCAT(' 외 ', COUNT(1) - 1, '건') ELSE '' END ) END FROM ( SELECT CONCAT( IFNULL(S.SITE_NM, T.SITE_CD) , CASE WHEN T.NODE_CD IS NOT NULL THEN CONCAT(' / ', IFNULL(N.NODE_NM, T.NODE_CD)) ELSE '' END ) AS LABEL , T.TARGET_SEQ FROM TB_NOTICE_TARGET T LEFT OUTER JOIN TB_SITE S ON S.CMPNY_CD = T.CMPNY_CD AND S.SITE_CD = T.SITE_CD LEFT OUTER JOIN TB_SITE_NODE N ON N.CMPNY_CD = T.CMPNY_CD AND N.SITE_CD = T.SITE_CD AND N.NODE_CD = T.NODE_CD WHERE T.CMPNY_CD = A.CMPNY_CD AND T.NOTICE_ID = A.NOTICE_ID ) TGT ) AS targetSummary FROM TB_NOTICE A LEFT OUTER JOIN TB_USER U ON U.CMPNY_CD = A.CMPNY_CD AND U.USER_CD = A.INSERT_NO LEFT OUTER JOIN TB_NOTICE_USER_ACK K ON K.CMPNY_CD = A.CMPNY_CD AND K.NOTICE_ID = A.NOTICE_ID AND K.USER_CD = #{gvUserCd} WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.NOTICE_TYPE = 'NOTICE' AND A.DEL_YN = 'N'
AND ( A.TITLE LIKE CONCAT('%', #{titleKeyword}, '%') OR A.CONTENT LIKE CONCAT('%', #{titleKeyword}, '%') )
AND A.POPUP_YN = #{popupYn}
AND A.PIN_YN = #{pinYn}
AND A.INSERT_DATE >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')
AND A.INSERT_DATE <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')
AND ( A.TARGET_SCOPE = 'ALL' OR EXISTS ( SELECT 1 FROM TB_NOTICE_TARGET T WHERE T.CMPNY_CD = A.CMPNY_CD AND T.NOTICE_ID = A.NOTICE_ID AND T.SITE_CD = #{siteCd}
AND ( T.NODE_CD = #{nodeCd} OR T.NODE_CD IS NULL OR ( T.INCLUDE_DESCENDANTS_YN = 'Y' AND EXISTS ( WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = T.CMPNY_CD AND N.SITE_CD = T.SITE_CD AND N.NODE_CD = T.NODE_CD UNION ALL SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT 1 FROM node_tree TT WHERE TT.NODE_CD = #{nodeCd} ) ) )
) )
ORDER BY A.PIN_YN DESC, A.PIN_ORDER ASC, A.INSERT_DATE DESC

mapper.insert:
/* Notice01Mapper.insertNotice */
INSERT INTO TB_NOTICE
(
    CMPNY_CD
  , NOTICE_ID
  , NOTICE_TYPE
  , TITLE
  , CONTENT
  , EDIT_PWD
  , TARGET_SCOPE
  , INCLUDE_DAILY_YN
  , POPUP_YN
  , POPUP_FROM_YMD
  , POPUP_TO_YMD
  , PIN_YN
  , PIN_ORDER
  , DEL_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{noticeId}
  , 'NOTICE'  
  , #{title}
  , #{content}
  , #{editPwdHash}
  , #{targetScope}
  , #{includeDailyYn}
  , #{popupYn}
  , #{popupFromYmd}
  , #{popupToYmd}
  , #{pinYn}
  , #{pinOrder}
  , 'N'
  , #{gvUserCd}
  , NOW()
)

mapper.update:
/* Notice01Mapper.updateNotice */
UPDATE TB_NOTICE
SET
    TITLE            = #{title}
  , CONTENT          = #{content}
  , TARGET_SCOPE     = #{targetScope}
  , INCLUDE_DAILY_YN = #{includeDailyYn}
  , POPUP_YN         = #{popupYn}
  , POPUP_FROM_YMD   = #{popupFromYmd}
  , POPUP_TO_YMD     = #{popupToYmd}
  , PIN_YN           = #{pinYn}
  , PIN_ORDER        = #{pinOrder}
  , UPDATE_NO        = #{gvUserCd}
  , UPDATE_DATE      = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND NOTICE_ID = #{noticeId}
  AND NOTICE_TYPE = 'NOTICE'  
  AND DEL_YN = 'N'

