INSERT INTO TB_NOTICE_TARGET
(
    CMPNY_CD
  , NOTICE_ID
  , TARGET_SEQ
  , SITE_CD
  , NODE_CD
  , INCLUDE_DESCENDANTS_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES

(
