  , #{noticeId}
  , #{idx} + 1
  , #{t.siteCd}
  , #{t.nodeCd}
  , IFNULL(#{t.includeDescendantsYn}, 'Y')
  , #{gvUserCd}
  , NOW()
)

/* Notice01Mapper.insertNoticeFiles */
INSERT INTO TB_NOTICE_FILE
(
    CMPNY_CD
  , NOTICE_ID
  , FILE_MGMT_CD
  , SORT_IDX
  , INSERT_NO
  , INSERT_DATE
)
VALUES

(
    #{gvCmpnyCd}
  , #{noticeId}
  , #{f.fileMgmtCd}
  , IFNULL(#{f.sortIdx}, #{idx} + 1)
  , #{gvUserCd}
  , NOW()
)

