/* Notice01Mapper.updateNoticeDelYn */
UPDATE TB_NOTICE
SET
    DEL_YN      = 'Y'
  , PIN_YN      = 'N'
  , PIN_ORDER   = NULL
  , UPDATE_NO   = #{gvUserCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND NOTICE_ID = #{noticeId}
  AND NOTICE_TYPE = 'NOTICE'  
  AND DEL_YN = 'N'

