/* Notice01Mapper.selectPinnedCountForUpdate */
SELECT
    COUNT(1)
FROM TB_NOTICE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.NOTICE_TYPE = 'NOTICE'  
  AND A.DEL_YN = 'N'
  AND A.PIN_YN = 'Y'

    AND A.NOTICE_ID != #{excludeNoticeId}

FOR UPDATE

mapper.update:
/* Notice01Mapper.shiftPinOrderUp */
UPDATE TB_NOTICE
SET
    PIN_ORDER   = PIN_ORDER + 1
  , UPDATE_NO   = #{gvUserCd}
  , UPDATE_DATE = UPDATE_DATE
WHERE CMPNY_CD = #{cmpnyCd}
  AND NOTICE_TYPE = 'NOTICE'  
  AND DEL_YN = 'N'
  AND PIN_YN = 'Y'
  AND PIN_ORDER >= #{fromOrder}

    AND NOTICE_ID != #{excludeNoticeId}

mapper.insert:
/* Notice01Mapper.upsertNoticeAck */
INSERT INTO TB_NOTICE_USER_ACK
(
    CMPNY_CD
  , NOTICE_ID
  , USER_CD
  , ACK_TYPE
  , SNOOZE_UNTIL_YMD
  , LAST_READ_DATE
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{noticeId}
  , #{gvUserCd}
  , #{ackType}
  , #{snoozeUntilYmd}
  , NOW()
  , #{gvUserCd}
  , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    ACK_TYPE         = NEW.ACK_TYPE
  , SNOOZE_UNTIL_YMD = NEW.SNOOZE_UNTIL_YMD
  , LAST_READ_DATE   = NOW()
  , UPDATE_NO        = #{gvUserCd}
  , UPDATE_DATE      = NOW()

/* Notice01Mapper.upsertNoticeRead */
INSERT INTO TB_NOTICE_USER_ACK
(
    CMPNY_CD
  , NOTICE_ID
  , USER_CD
  , ACK_TYPE
  , LAST_READ_DATE
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{noticeId}
  , #{gvUserCd}
  , 'READ'
  , NOW()
  , #{gvUserCd}
  , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    LAST_READ_DATE = NOW()
  , UPDATE_NO      = #{gvUserCd}
  , UPDATE_DATE    = NOW()

